/*
 Problem: 3870. Count Commas in Range
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 8.4 MB (84.48%)
 Tags: Math
*/
class Solution {
public:
    int countCommas(int n) {
        int ans = 0;
        for (long long p = 1000; p <= n; p *= 1000)
            ans += n - p + 1;

        return ans;
    }
};
